function decimalParts(value){var s=String(value).trim();var m=/^([+-]?)(\d+)(?:\.(\d*))?$/.exec(s);if(!m)return null;var sign=m[1]==='-'?-1:1;var integer=m[2].replace(/^0+(?=\d)/,'');var fraction=(m[3]||'').replace(/0+$/,'');if(/^0+$/.test(integer)&&!fraction)sign=1;return{sign:sign,integer:integer,fraction:fraction};}
