function normalizeDistribution(distribution){if(!distribution||typeof distribution!=='object'||Array.isArray(distribution))throw new Error('distribution must be an object');if(typeof distribution.id!=='string'||!distribution.id.trim())throw new Error('distribution id is required');if(!Array.isArray(distribution.values))throw new Error('distribution values must be an array');return{id:distribution.id,label:typeof distribution.label==='string'&&distribution.label!==''?distribution.label:distribution.id,values:distribution.values.map(function(item,index){if(!item||typeof item!=='object'||Array.isArray(item))throw new Error('distribution value at index '+index+' must be an object');var count=Number(item.count);if(!Number.isFinite(count)||count<0)throw new Error('distribution count must be a non-negative finite number at index '+index);return{value:item.value,count:count};})};}
